export const audioArchive: CanonicalAudioEntity[] = CANONICAL_AUDIO_ARCHIVE;

export function getAudioByCanonicalId(id: string): CanonicalAudioEntity | undefined {
  return CANONICAL_AUDIO_ARCHIVE.find((a) => a.canonicalId === id);
}

export function getAudioByCategory(category: CanonicalCategorySlug): CanonicalAudioEntity[] {
  return CANONICAL_AUDIO_ARCHIVE.filter((a) => a.category === category);
}

export function getAudioContainers(): CanonicalAudioEntity[] {
  return CANONICAL_AUDIO_ARCHIVE.filter((a) => a.isContainer);
}

export function getAudioTracks(): CanonicalAudioEntity[] {
  return CANONICAL_AUDIO_ARCHIVE.filter((a) => !a.isContainer);
}
